INSERT INTO recipes (title, meal_type, source_type, calories, protein_g, carbs_g, fat_g, instructions, tags, status) VALUES
('Waffle egg sandwich','breakfast','local',850,90,29,41,'Într-un blender punem 1 ou, albușul, făina, sare și praf de copt, apoi mixăm.
Prăjim compoziția în waffle maker (ies aproximativ 4 waffle).
Prăjim cubulețele de porc și facem ochiuri din cele 4 ouă rămase.
Când waffle-urile sunt gata, le ungem cu cream cheese, punem ouăle, feliile de cheddar, prosciutto și salamul.
Închidem cu cealaltă parte de waffle și le punem în tigaie cu capac peste, ca să se topească cașcavalul.
Putem folosi sosuri 0kcal.','{"high-protein","fat-loss","savory","meal-prep","gym-friendly"}','active'),
('Salată de ouă','breakfast','local',529,54,16,27,'Punem 4 ouă la fiert pentru 7-8 minute.
Prăjim baconul, iar când e 90% gata punem peste albușul de ou și îl prăjim împreună.
Punem ouăle fierte într-un bol, le zdrobim, adăugăm cream cheese, albușul cu bacon și amestecăm până iese o consistență cremoasă.
Putem unge pe felia de pâine sau o mâncăm alături; pâinea se poate și prăji.','{"high-protein","low-calorie","savory","quick-meal"}','active'),
('Burger de pui','lunch','local',1140,147,76,27,'Tăiem puiul în felii și condimentăm după gust (sare, piper, usturoi, boia dulce/afumat/iute).
Prăjim în tigaie la foc mic spre mediu, de preferat fără ulei sau cu foarte puțin spray de ulei, cu capac peste pentru a ieși fraged; întoarcem din 2 în 2 minute.
Punem peste feliile de cheddar proteic și capacul ca să se topească.
În același timp tăiem chiflele în jumătate și le prăjim în tigaie.
Asamblăm puiul în chiflă și adăugăm sosuri 0kcal, salată, roșii și ceapă după plac.','{"high-protein","fat-loss","comfort-food","savory","gym-friendly"}','active'),
('Wrap cu pui și bacon','lunch','local',600,66,34,21,'Tăiem puiul în cubulețe și condimentăm după gust.
Prăjim baconul, îl scoatem, iar în grăsimea rămasă prăjim pieptul de pui.
Când e gata, adăugăm baconul, cream cheese și cașcavalul, ținem focul la minim până se topește tot.
Punem în lipie, închidem și prăjim wrap-ul în tigaie.','{"high-protein","low-calorie","savory","quick-meal"}','active'),
('Mac and cheese cu pui','lunch','local',940,95,83,24,'Punem macaroanele la fiert 8-10 minute.
Tăiem puiul în cubulețe și condimentăm după gust.
Prăjim puiul în tigaie fără ulei sau cu puțin spray de ulei.
Când puiul și pastele sunt gata, le combinăm în tigaie, adăugăm smântâna de gătit, mozzarella light și puțină apă de la paste.
Amestecăm la foc minim până se topește și obținem o compoziție cremoasă.','{"high-protein","comfort-food","savory","meal-prep"}','active'),
('Carbonara cu pui','lunch','local',1000,100,80,29,'Punem pastele la fiert 8-10 minute.
Tăiem puiul în cubulețe și condimentăm după gust (sare, piper, usturoi).
Prăjim baconul, îl scoatem și prăjim puiul în grăsimea rămasă.
Adăugăm baconul, pastele, smântâna de gătit și puțină apă de la paste; amestecăm la foc minim până devine cremos.
Punem în farfurie și adăugăm parmezan ras peste.','{"high-protein","comfort-food","savory","meal-prep"}','active'),
('Spaghete bolognese','lunch','local',1050,93,97,28,'Punem pastele la fiert 8-10 minute.
Prăjim carnea de vită, adăugăm sosul de roșii și sosul de bolognese, amestecăm puțin.
Adăugăm pastele în tigaie împreună cu felia de cheddar până ajunge la consistența dorită.
Adăugăm parmezanul ras peste.
Se poate împărți și în 2 mese.','{"high-protein","comfort-food","savory","meal-prep"}','active'),
('Sandwich proteic','lunch','local',1020,100,102,22,'Tăiem pâinea în jumătate și scoatem miezul (ajungem la 180-200g).
Ungem cu cream cheese și adăugăm restul ingredientelor.
Putem mânca alături roșii, castraveți și ardei după plac (adaugă 50-100 kcal).','{"high-protein","savory","quick-meal"}','active'),
('Piure cu pui și varză','lunch','local',600,75,51,10,'Tăiem pieptul de pui în cubulețe/felii, condimentăm după gust și îl prăjim fără ulei.
Preparăm piureul instant conform instrucțiunilor de pe ambalaj.
Peste varză punem sare și oțet după gust.','{"high-protein","low-calorie","low-fat","savory"}','active'),
('Pizza proteică','lunch','local',910,82,85,26,'Amestecăm făina și skyr-ul/iaurtul grecesc într-un bol până obținem un aluat.
Întindem aluatul pe o foaie de copt și îl coacem 8-10 minute la 200°C.
Scoatem din cuptor, ungem cu sos de roșii și adăugăm prosciutto, mozzarella light, salam de curcan, cubulețele de șuncă și porumbul.
Punem înapoi în cuptor 12-15 minute la 200°C (gradele și timpul pot varia).','{"high-protein","comfort-food","savory","meal-prep"}','active'),
('Pollo parmigiana','lunch','local',1000,131,65,24,'Folosim șnițel pre-pregătit de la frigider (nu cel prăjit în ulei) sau îl facem din piept de pui trecut prin albuș de ou și pesmet.
Punem șnițelul într-o tavă cu hârtie de copt și dăm foarte puțin spray de ulei pe ambele părți.
Coacem 10-15 minute la 200-220°C, întoarcem și mai lăsăm 5-8 minute.
Adăugăm sosul de roșii, feliile de cheddar rupte și parmezanul ras; punem în cuptor câteva minute cât să se topească cașcavalul.','{"high-protein","comfort-food","savory","meal-prep"}','active'),
('Breakfast wrap','breakfast','local',508,52,8,26,'Punem cubulețele de șuncă și salamul într-o tigaie de mărimea lipiei și prăjim până sunt 75% gata.
Turnăm peste ouăle și albușul bătute, plus feliile de cheddar rupte; punem capacul și ținem focul la minim.
Când e aproape gata dar partea de sus încă lipicioasă, punem lipia și întoarcem ca să se prăjească și ea.','{"high-protein","low-calorie","savory","quick-meal"}','active'),
('Loaded fries','lunch','local',1050,105,68,37,'Tăiem cartofii (sau folosim cartofi congelați neprăjiți), îi fierbem 5-8 minute, apoi îi punem la airfryer cu puțin spray de ulei și condimente, 15-20 minute la 200°C.
Prăjim baconul, iar în grăsimea rămasă prăjim carnea de vită.
Pentru sosul de cheddar: topim untul, adăugăm făina și amestecăm, apoi turnăm treptat laptele amestecând continuu.
Adăugăm feliile de cheddar rupte, condimentăm cu sare și boia dulce; ajustăm consistența cu lapte.
Punem cartofii, vita și baconul într-un bol și turnăm sosul de cheddar peste.','{"high-protein","comfort-food","savory"}','active'),
('Pui cu cartofi','lunch','local',474,58,45,8,'Tăiem puiul în cubulețe/felii, condimentăm după plac (sare, piper, boia dulce/iute, usturoi) și îl prăjim fără ulei.
Fierbem cartofii 5-8 minute, apoi îi punem la airfryer cu puțin spray de ulei și condimente, 15-20 minute la 200°C.
În iaurt punem sare, piper, oregano și usturoi pentru un sos alb cu usturoi.','{"high-protein","low-calorie","low-fat","savory"}','active'),
('Salată cu pui și parmezan','lunch','local',719,100,22,24,'Tăiem pieptul de pui cubulețe, condimentăm după gust (sare, piper, boia dulce/iute, oregano, usturoi) și prăjim în tigaie fără ulei.
Punem salata, porumbul și telemeaua în bol.
Adăugăm peste pieptul de pui, sosurile 0 și parmezanul.','{"high-protein","low-fat","savory","quick-meal"}','active'),
('Shaorma la farfurie','lunch','local',690,74,73,12,'Punem cartofii la airfryer la 180-200°C pentru 15-20 minute.
Tăiem pieptul de pui cubulețe, condimentăm și punem în bol cu iaurtul, mierea și sosul bbq; lăsăm la marinat 5-10 minute (sau peste noapte).
Prăjim puiul marinat.
Pregătim restul ingredientelor pe o farfurie și adăugăm puiul și cartofii.
Putem face sos alb cu usturoi sau folosi sosuri 0kcal.','{"high-protein","savory","comfort-food"}','active'),
('Șnițel cu cartofi și telemea','lunch','local',1035,100,117,20,'Punem șnițelul într-o tavă cu hârtie de copt și dăm foarte puțin spray de ulei pe ambele părți.
Coacem 10-15 minute la 200-220°C, întoarcem și mai lăsăm 5-8 minute până e auriu.
Punem cartofii la airfryer la 180-200°C pentru 15-20 minute.
Când sunt gata, adăugăm telemea peste cartofi.','{"high-protein","comfort-food","savory"}','active'),
('Fâșii de pui','lunch','local',874,103,90,12,'Punem cartofii la airfryer la 180-200°C pentru 15-20 minute.
Punem puiul la fiert 25-30 minute, până îl putem sfâșia cu furculița.
Facem sos alb cu usturoi din iaurt grecesc (sare, piper, oregano, usturoi).
Punem cartofii în bol, adăugăm puiul sfâșiat, sosul de usturoi și sosul bbq.','{"high-protein","low-fat","savory","meal-prep"}','active'),
('Steak sandwich','lunch','local',1230,123,108,34,'Punem steak-ul în congelator 1-2h ca să-l putem tăia subțire.
Tăiem în fâșii subțiri, separăm părțile cu grăsime (le păstrăm), condimentăm și punem înapoi în congelator.
Tăiem ceapa și ardeiul; încingem o tigaie cu grăsimea de la steak și caramelizăm ceapa și ardeiul, condimentăm.
Tăiem pâinea în jumătate și scoatem miezul (180-200g).
Prăjim steak-ul în tigaia preîncălzită la foc maxim 1-2 minute, adăugăm ardeiul, ceapa și cașcavalul; amestecăm până se topește și punem tot în pâine.
Putem folosi sosuri 0kcal.','{"high-protein","comfort-food","savory"}','active'),
('Sandwich cu vită','lunch','local',1100,112,108,18,'Tăiem ceapa și ardeiul; încingem o tigaie cu foarte puțin ulei și caramelizăm ceapa și ardeiul.
Tăiem pâinea în jumătate și scoatem miezul (180-200g).
Prăjim carnea de vită, adăugăm ardeiul, ceapa și cașcavalul; amestecăm până se topește și punem tot în pâine.
Putem folosi sosuri 0kcal.','{"high-protein","low-fat","comfort-food","savory"}','active'),
('Chili con carne','lunch','local',930,99,58,25,'Prăjim cubulețele de șuncă, apoi adăugăm carnea de vită peste și condimentăm (sare, piper, boia dulce/iute, oregano, chilli).
Când carnea e prăjită, adăugăm cutia de fasole, sosul de roșii și feliile de cheddar.
Amestecăm până se topește cașcavalul.','{"high-protein","comfort-food","savory"}','active'),
('Double smash burger','lunch','local',1130,122,70,35,'Facem 4 biluțe egale din carnea de vită și le presăm subțire (smash) în tigaie.
Prăjim cubulețele de șuncă, iar când sunt 50% gata adăugăm ceapa tăiată și le prăjim împreună.
Prăjim carnea de vită; după ce o întoarcem punem peste feliile de cheddar să se topească.
Tăiem chiflele în jumătate și le prăjim.
Asamblăm: paveluțele de carne în chiflă, ceapa caramelizată cu bacon și sosuri 0kcal (bbq, truffle mayo, sos de burger).','{"high-protein","comfort-food","savory","gym-friendly"}','active'),
('Protein tacos','lunch','local',850,106,9,35,'Întindem carnea de vită egal pe cele 3 lipii proteice și presărăm cubulețele de șuncă în carne.
Punem la prăjit până se prăjește de tot ca să nu se dezlipească carnea, apoi întoarcem să se prăjească și lipia.
Punem feliile de cheddar proteic, îndoim în 2 și lăsăm câteva secunde pe ambele părți.
Servim cu sosuri 0kcal sau sos de usturoi.','{"high-protein","comfort-food","savory","gym-friendly"}','active'),
('Înghețată proteică','dessert','local',399,53,27,8,'Adăugăm pudra proteică în skyr (se poate înlocui cu iaurt grecesc, dar scad proteinele) și amestecăm până se omogenizează.
Punem în congelator 1-2h, amestecând din 30 în 30 minute pentru o compoziție cât mai bună.
Când are consistența dorită, adăugăm oreo sfărâmat.','{"high-protein","low-calorie","sweet","low-fat"}','active'),
('Clătite americane','breakfast','local',440,50,31,13,'Adăugăm albușul, oul, banana, ovăzul, iaurtul, scorțișoara, praful de copt și îndulcitorul în blender.
Compoziția e mai lichidă, așa că prăjim în tigaie mică pentru a ieși pufoase.
Pentru ciocolată: amestecăm pudra proteică, untul de arahide și pudra de cacao cu 25ml apă, ajustând consistența.
Putem adăuga căpșuni sau 15-20g afine.','{"high-protein","low-calorie","sweet"}','active'),
('Clătite americane 2','breakfast','local',530,58,49,12,'Adăugăm iaurtul, oul, făina, praful de copt și îndulcitorul într-un bol; mixăm până nu mai există cocoloașe.
În brânza de vaci adăugăm îndulcitor după gust.
Punem compoziția în tigaie, formăm clătitele, presărăm bucățile de ciocolată și le întoarcem pe rând.
Când sunt gata, punem brânza peste (opțional câteva afine).','{"high-protein","sweet"}','active'),
('French toast','breakfast','local',522,52,59,8,'Amestecăm albușul, scorțișoara și îndulcitorul într-un bol.
Înmuiem pâinea în albuș 1 minut, apoi punem feliile în tigaie (foc minim spre mediu) cu puțin spray de ulei.
Apăsăm afinele în pâine, apoi întoarcem feliile.
Pentru ciocolată: amestecăm pudra proteică, untul de arahide și pudra de cacao cu 25ml apă, ajustând consistența.','{"high-protein","low-fat","sweet"}','active'),
('Clătite cu brânză','breakfast','local',515,77,31,10,'Adăugăm toate ingredientele în blender, mai puțin brânza de vaci (îndulcitor și coajă de lămâie după gust).
Prăjim în tigaie cu foarte puțin spray de ulei.
În brânză punem îndulcitor și coajă de lămâie.
Umplem clătitele cu brânza.','{"high-protein","low-fat","sweet"}','active'),
('Nutella proteic','dessert','local',200,24,9,7,'Adăugăm toate ingredientele într-un bol împreună cu 20-25ml apă, amestecăm și ajustăm consistența cu apă la nevoie.','{"high-protein","low-calorie","sweet","low-fat"}','active'),
('Sos de usturoi','sauce','local',58,8,4,2,'Amestecăm toate ingredientele până obținem un sos de usturoi gustos și slab caloric.
Opțional adăugăm boia iute și chilli pentru picant.','{"low-calorie","low-fat","savory","sauce"}','active');